definition.script:
var tenantId = input.get('tenantId');
var clientId = input.get('clientId');
var clientSecret = input.get('clientSecret');
var refreshToken = input.get('refreshToken');
var resource = input.get('resource') || 'https://api.partnercenter.microsoft.com';
var scope = input.get('scope') || 'openid';

if (!tenantId || !clientId || !clientSecret || !refreshToken) {
    output.set('HasErrors', true);
    output.set('ErrorMessage', 'TenantId, ClientId, ClientSecret, and RefreshToken are required');
    output.set('AccessToken', '');
    tags.trigger('error');
} else {
    try {
        var tokenUrl = 'https://login.microsoftonline.com/' + tenantId + '/oauth2/token';

        var formData = {
            resource: resource,
            client_id: clientId,
            client_secret: clientSecret,
            grant_type: 'refresh_token',
            refresh_token: refreshToken,
            scope: scope
        };

        log.info('Requesting token from: ' + tokenUrl);
        log.debug('Resource: ' + resource);

        var response = http.postForm(tokenUrl, formData);

        if (response.isSuccess) {
            var tokenResponse = json.parse(response.body);

            if (tokenResponse && tokenResponse.access_token) {
                output.set('AccessToken', tokenResponse.access_token);
                output.set('TokenType', tokenResponse.token_type || 'Bearer');
                output.set('ExpiresIn', tokenResponse.expires_in || 0);
                output.set('ExpiresOn', tokenResponse.expires_on || '');
                output.set('Resource', tokenResponse.resource || resource);
                output.set('Scope', tokenResponse.scope || scope);

                if (tokenResponse.refresh_token) {
                    output.set('NewRefreshToken', tokenResponse.refresh_token);
                } else {
                    output.set('NewRefreshToken', refreshToken);
                }

                output.set('HasErrors', false);
                output.set('ErrorMessage', '');
                output.set('StatusCode', response.statusCode);

                log.info('Token refreshed successfully, expires in ' + tokenResponse.expires_in + 's');
                tags.trigger('success');
            } else {
                throw new Error('No access_token in response');
            }
        } else {
            var errorBody = response.body;
            var errorMsg = 'Token refresh failed: HTTP ' + response.statusCode;

            try {
                var errorJson = json.parse(errorBody);
                if (errorJson.error_description) {
                    errorMsg = errorJson.error_description;
                } else if (errorJson.error) {
                    errorMsg = errorJson.error;
                }
            } catch (e) {}

            log.error(errorMsg, errorBody);
            output.set('HasErrors', true);
            output.set('ErrorMessage', errorMsg);
            output.set('AccessToken', '');
            output.set('StatusCode', response.statusCode);
            tags.trigger('error');
        }

    } catch (ex) {
        log.error('Token refresh exception: ' + ex.message);
        output.set('HasErrors', true);
        output.set('ErrorMessage', ex.message);
        output.set('AccessToken', '');
        tags.trigger('error');
    }
}
